args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const base = 'http://127.0.0.1:3100'
const ids = new Set()
const uuidPattern = /"'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const home = await fetch(base)
const html = await home.text()
const asset = html.match(/(?:src|href)="([''^'"\\\"]*\\/_next\\/static\\/["'^'"\\\"]+)\"/)?.[1]
assert.ok(asset, 'Expected a static asset in the page')
for (const path of ['/', '/?check=request-id', '/missing-path?check=pathname', asset.replaceAll('&amp;', '&')]) {
  const response = await fetch(new URL(path, base))
  const id = response.headers.get('X-Request-Id')
  assert.match(id ?? '', uuidPattern)
  assert.ok("'!ids.has(id), '"'Each response must have a unique request ID')
  ids.add(id)
  await response.arrayBuffer()
  console.log("'`${response.status} ${path}: valid unique request ID`)
}
NODE'

